from collections import deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   for x,y in q:
    cells.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   out.append(cells)
 return sorted(out,key=len,reverse=True)

